"""Publish actual optimizer coordinates and selected values from its manifest."""
import json,sys
from pathlib import Path
from atmo_scoops.transient.plate_optimize import encode
out=Path(sys.argv[1]);m=json.loads((out/'manifest.json').read_text());p=out/'selected_config.json';c=json.loads(p.read_text()) if p.exists() else m['base'];x=encode(c,m['coordinates'])
lines=['# Valve-reserve constrained coordinates','',f"The search has **{len(x)} independent scalar coordinates**. Values below come from `{'selected_config.json' if p.exists() else 'manifest baseline (search pending)'}` in `{out}`.",'','| Coordinate | Lower bound | Selected / baseline | Upper bound |','|---|---:|---:|---:|']
for u,s in zip(x,m['coordinates']):
 v=s['low']*(s['high']/s['low'])**u
 lines.append(f"| `{s['key']}` | {s['low']:.7g} | {v:.7g} | {s['high']:.7g} |")
lines+=['','Indices are zero-based. `solid_depth` multiplied by the fixed full-bore area gives metal volume. `thermal_gap_m` is effective thermal spacing: physical gap = rows × (effective gap + thickness) − thickness. Main receiver rack depth is recomputed at its narrower area while preserving metal inventory.','', 'Fixed: 30 m bore, 31.7 m external diameter, 317 m hull, 125 m reserve length, 2,000 km apogee, SiC then Al materials, four staggered plate rows, 10 m/s deployment speed, receiver pressure target 4,766.83 Pa and 6,500 Pa rating. Valve and feed passage areas are capability assumptions, not optimizer controls.','', 'Derived before each cycle: main receiver radius and volume after packages; reserve volume including heads; total dry mass; installed bus and battery discharge power; gas and product processing schedules. Receiver operating temperature is an integrated state, not a prescribed fill temperature.','', 'Constraints include reserve species/energy closure, rack enthalpy closure, battery/warm energy closure, gas/rotor residuals, full thrust, pressure/material/electrical limits, rack regime/fit, storage capacity, capture ≥99.9%, and receiver peak pressure within 50 Pa of target. Search-only safety buffers tighten reserve closure and receiver matching for subsequent resolution validation.','', 'The objective is dry mass / net new useful liquid per cycle × orbital period. It is operating-orbit mass payoff; circular-apogee delivery is not implemented.']
Path('modeling/optimization/VALVE_COORDINATES.md').write_text('\n'.join(lines)+'\n')
